def build_message(
    topic_name: str,
    date_sent: float,
    message_id: int,
    content: str,
    rendered_content: Optional[str],
    user_id: int,
    recipient_id: int,
    has_image: bool = False,
    has_link: bool = False,
    has_attachment: bool = True,
) -> ZerverFieldsT:
    zulip_message = Message(
        rendered_content_version=1,
        date_sent=date_sent,
        id=message_id,
        content=content,
        rendered_content=rendered_content,
        has_image=has_image,
        has_attachment=has_attachment,
        has_link=has_link,
    )
    zulip_message.set_topic_name(topic_name)
    zulip_message_dict = model_to_dict(
        zulip_message, exclude=["recipient", "sender", "sending_client"]
    )
    zulip_message_dict["sender"] = user_id
    zulip_message_dict["sending_client"] = 1
    zulip_message_dict["recipient"] = recipient_id
    return zulip_message_dict

def render_description(text, content_type):
    """Render Description field to HTML"""
    if re.match(r'^.+(\n {8}.*)+\n?$', text):
        text = re.sub(r'^ {8}', '', text, flags=re.MULTILINE)
    if content_type == 'text/x-rst':
        html = publish_parts(
            text, writer_name='html',
            settings_overrides={'syntax_highlight': 'short'})['html_body']
    elif content_type == 'text/markdown':
        html = markdown(text, extensions=[GithubFlavoredMarkdownExtension()])
    else:
        html = format_html('<pre>{}</pre>', text)
    return mark_safe(html)

