        fp,
        b"IHDR",
        o32(im.size[0]),
        o32(im.size[1]),
        mode,
        b"\0",
        b"\0",
        b"\0",
    )
    chunks = [b"cHRM", b"gAMA", b"sBIT", b"sRGB", b"tIME"]
    icc = im.encoderinfo.get("icc_profile", im.info.get("icc_profile"))
    if icc:
        name = b"ICC Profile"
        data = name + b"\0\0" + zlib.compress(icc)
        chunk(fp, b"iCCP", data)
        chunks.remove(b"sRGB")
