            exif = exif[6:]
        chunk(fp, b"eXIf", exif)
    if save_all:
        _write_multiple_frames(im, fp, chunk, rawmode)
    else:
        ImageFile._save(im, _idat(fp, chunk), [("zip", (0, 0) + im.size, 0, rawmode)])
    if info:
        for info_chunk in info.chunks:
            cid, data = info_chunk[:2]
            if cid[1:2].islower():
                after_idat = info_chunk[2:3]
                if after_idat:
                    chunk(fp, cid, data)
    chunk(fp, b"IEND", b"")
    if hasattr(fp, "flush"):
