                    ima_measurement_list=None, allowlist={}, hash_alg=None, ima_keyrings=None,
                    mb_measurement_list=None, mb_refstate=None) -> Failure:
        retout, success = self._tpm2_checkquote(aikTpmFromRegistrar, quote, nonce, hash_alg)
