            "PCX version %s, bits %s, planes %s, stride %s",
            version,
            bits,
            planes,
            provided_stride,
        )
        self.info["dpi"] = i16(s, 12), i16(s, 14)
        if bits == 1 and planes == 1:
            mode = rawmode = "1"
        elif bits == 1 and planes in (2, 4):
            mode = "P"
            rawmode = "P;%dL" % planes
