        version, bits, planes, rawmode = SAVE[im.mode]
    except KeyError as e:
        raise ValueError(f"Cannot save {im.mode} images as PCX") from e
    stride = (im.size[0] * bits + 7) // 8
    stride += stride % 2
    logger.debug(
        "PcxImagePlugin._save: xwidth: %d, bits: %d, stride: %d",
        im.size[0],
        bits,
        stride,
    )
    screen = im.size
    dpi = 100, 100
