        queue_cache_key, component_requests, timeout=get_serial_timeout(),
    )
    if len(component_requests) > 1:
        original_epoch = component_requests[0].epoch
        return {
            "queued": True,
            "epoch": component_request.epoch,
            "original_epoch": original_epoch,
