        try:
            msg = next(download_iter)
        except StopIteration:
            self._update_table_status()
            afterid = self.top.after(10, self._show_progress, 0)
            self._afterid['_download_cb'] = afterid
            return
        def show(s):
            self._progresslabel['text'] = s
            self._log(s)
