    async def _has_watch_regex_match(self, text: str) -> Tuple[Union[bool, re.Match], Optional[str]]:
        """
        Return True if `text` matches any regex from `word_watchlist` or `token_watchlist` configs.
        `word_watchlist`'s patterns are placed between word boundaries while `token_watchlist` is
        matched as-is. Spoilers are expanded, if any, and URLs are ignored.
        Second return value is a reason written to database about blacklist entry (can be None).
        """
        if SPOILER_RE.search(text):
            text = self._expand_spoilers(text)
        text = self.clean_input(text)
        if URL_RE.search(text):
            return False, None
        watchlist_patterns = self._get_filterlist_items('filter_token', allowed=False)
        for pattern in watchlist_patterns:
            match = re.search(pattern, text, flags=re.IGNORECASE)
            if match:
                return match, self._get_filterlist_value('filter_token', pattern, allowed=False)['comment']
        return False, None
    async def _has_urls(self, text: str) -> Tuple[bool, Optional[str]]:
        domain_blacklist = self._get_filterlist_items("domain_name", allowed=False)
class Snekbox(Cog):
    async def format_output(self, output: str) -> Tuple[str, Optional[str]]:
        """
        Format the output and return a tuple of the formatted output and a URL to the full output.
        Prepend each line with a line number. Truncate if there are over 10 lines or 1000 characters
        and upload the full output to a paste service.
        """
        log.trace("Formatting output...")
        output = output.rstrip("\n")
        original_output = output
        paste_link = None
        if "<@" in output:
            output = output.replace("<@", "<@\u200B")
        if "<!@" in output:
            output = output.replace("<!@", "<!@\u200B")
        if ESCAPE_REGEX.findall(output):
            paste_link = await self.upload_output(original_output)
            return "Code block escape attempt detected; will not output result", paste_link
        truncated = False
        lines = output.count("\n")
        if lines > 0:
            output = [f"{i:03d} | {line}" for i, line in enumerate(output.split('\n'), 1)]
            output = output[:11]
            output = "\n".join(output)
        if lines > 10:
            truncated = True
            if len(output) >= 1000:
                output = f"{output[:1000]}\n... (truncated - too long, too many lines)"
            else:
                output = f"{output}\n... (truncated - too many lines)"
        elif len(output) >= 1000:
            truncated = True
            output = f"{output[:1000]}\n... (truncated - too long)"
        if truncated:
            paste_link = await self.upload_output(original_output)
        output = output or "[No output]"
        return output, paste_link
    @command(name="eval", aliases=("e",))
    @guild_only()
    @redirect_output(
        destination_channel=Channels.bot_commands,
        bypass_roles=EVAL_ROLES,
        categories=NO_EVAL_CATEGORIES,
        channels=NO_EVAL_CHANNELS,
        ping_user=False
    )
    async def eval_command(self, ctx: Context, *, code: str = None) -> None:
        """
        Run Python code and get the results.
        This command supports multiple lines of code, including code wrapped inside a formatted code
        block. Code can be re-evaluated by editing the original message within 10 seconds and
        clicking the reaction that subsequently appears.
        We've done our best to make this sandboxed, but do let us know if you manage to find an
        issue with it!
        """
        if ctx.author.id in self.jobs:
            await ctx.send(
                f"{ctx.author.mention} You've already got a job running - "
                "please wait for it to finish!"
            )
            return
        if not code:
            await ctx.send_help(ctx.command)
            return
        if Roles.helpers in (role.id for role in ctx.author.roles):
            self.bot.stats.incr("snekbox_usages.roles.helpers")
        else:
            self.bot.stats.incr("snekbox_usages.roles.developers")
        if ctx.channel.category_id == Categories.help_in_use:
            self.bot.stats.incr("snekbox_usages.channels.help")
        elif ctx.channel.id == Channels.bot_commands:
            self.bot.stats.incr("snekbox_usages.channels.bot_commands")
        else:
            self.bot.stats.incr("snekbox_usages.channels.topical")
        log.info(f"Received code from {ctx.author} for evaluation:\n{code}")
        while True:
            self.jobs[ctx.author.id] = datetime.datetime.now()
            code = self.prepare_input(code)
            try:
                response = await self.send_eval(ctx, code)
            finally:
                del self.jobs[ctx.author.id]
            code = await self.continue_eval(ctx, response)
            if not code:
                break
            log.info(f"Re-evaluating code from message {ctx.message.id}:\n{code}")
async def send_to_paste_service(contents: str, *, extension: str = "") -> Optional[str]:
    """
    Upload `contents` to the paste service.
    `extension` is added to the output URL
    When an error occurs, `None` is returned, otherwise the generated URL with the suffix.
    """
    extension = extension and f".{extension}"
    log.debug(f"Sending contents of size {len(contents.encode())} bytes to paste service.")
    paste_url = URLs.paste_service.format(key="documents")
    for attempt in range(1, FAILED_REQUEST_ATTEMPTS + 1):
        try:
            async with bot.instance.http_session.post(paste_url, data=contents) as response:
                response_json = await response.json()
        except ClientConnectorError:
            log.warning(
                f"Failed to connect to paste service at url {paste_url}, "
                f"trying again ({attempt}/{FAILED_REQUEST_ATTEMPTS})."
            )
            continue
        except Exception:
            log.exception(
                f"An unexpected error has occurred during handling of the request, "
                f"trying again ({attempt}/{FAILED_REQUEST_ATTEMPTS})."
            )
            continue
        if "message" in response_json:
            log.warning(
                f"Paste service returned error {response_json['message']} with status code {response.status}, "
                f"trying again ({attempt}/{FAILED_REQUEST_ATTEMPTS})."
            )
            continue
        elif "key" in response_json:
            log.info(f"Successfully uploaded contents to paste service behind key {response_json['key']}.")
            paste_link = URLs.paste_service.format(key=response_json['key']) + extension
            if extension == '.py':
                return paste_link
            return paste_link + "?noredirect"
        log.warning(
            f"Got unexpected JSON response from paste service: {response_json}\n"
            f"trying again ({attempt}/{FAILED_REQUEST_ATTEMPTS})."
        )
class ModLog(Cog, name="ModLog"):
    @Cog.listener()
    async def on_member_update(self, before: discord.Member, after: discord.Member) -> None:
        """Log member update event to user log."""
        if before.guild.id != GuildConstant.id:
            return
        if before.id in self._ignored[Event.member_update]:
            self._ignored[Event.member_update].remove(before.id)
            return
        changes = self.get_role_diff(before.roles, after.roles)
        diff = DeepDiff(before, after, exclude_regex_paths=r".*\[.*")
        diff_values = {**diff.get("values_changed", {}), **diff.get("type_changes", {})}
        for attr, value in diff_values.items():
            if not attr:
                continue
            attr = attr[5:]
            attr = attr.replace("_", " ").replace(".", " ").capitalize()
            new = value.get("new_value")
            old = value.get("old_value")
            changes.append(f"**{attr}:** `{old}` **→** `{new}`")
        if not changes:
            return
        message = ""
        for item in sorted(changes):
            message += f"{Emojis.bullet} {item}\n"
        message = f"{format_user(after)}\n{message}"
        await self.send_log_message(
            icon_url=Icons.user_update,
            colour=Colour.og_blurple(),
            title="Member updated",
            text=message,
            thumbnail=after.display_avatar.url,
            channel_id=Channels.user_log
        )
class AntiMalware(Cog):
    @Cog.listener()
    async def on_message(self, message: Message) -> None:
        """Identify messages with prohibited attachments."""
        if not message.attachments or not message.guild:
            return
        if message.webhook_id or message.author.bot:
            return
        if getattr(message.channel, "category", None) and message.channel.category.name == JAM_CATEGORY_NAME:
            return
        if hasattr(message.author, "roles") and any(role.id in Filter.role_whitelist for role in message.author.roles):
            return
        embed = Embed()
        extensions_blocked = self._get_disallowed_extensions(message)
        blocked_extensions_str = ', '.join(extensions_blocked)
        if ".py" in extensions_blocked:
            embed.description = PY_EMBED_DESCRIPTION
        elif extensions := TXT_LIKE_FILES.intersection(extensions_blocked):
            cmd_channel = self.bot.get_channel(Channels.bot_commands)
            embed.description = TXT_EMBED_DESCRIPTION.format(
                blocked_extension=extensions.pop(),
                cmd_channel_mention=cmd_channel.mention
            )
        elif extensions_blocked:
            meta_channel = self.bot.get_channel(Channels.meta)
            embed.description = DISALLOWED_EMBED_DESCRIPTION.format(
                joined_whitelist=', '.join(self._get_whitelisted_file_formats()),
                blocked_extensions_str=blocked_extensions_str,
                meta_channel_mention=meta_channel.mention,
            )
        if embed.description:
            log.info(
                f"User '{message.author}' ({message.author.id}) uploaded blacklisted file(s): {blocked_extensions_str}",
                extra={"attachment_list": [attachment.filename for attachment in message.attachments]}
            )
            await message.channel.send(f"Hey {message.author.mention}!", embed=embed)
            try:
                await message.delete()
            except NotFound:
                log.info(f"Tried to delete message `{message.id}`, but message could not be found.")
class Bot(commands.Bot):
    def _connect_statsd(self, statsd_url: str, retry_after: int = 2, attempt: int = 1) -> None:
        """Callback used to retry a connection to statsd if it should fail."""
        if attempt >= 8:
            log.error("Reached 8 attempts trying to reconnect AsyncStatsClient. Aborting")
            return
        try:
            self.stats = AsyncStatsClient(self.loop, statsd_url, 8125, prefix="bot")
        except socket.gaierror:
            log.warning(f"Statsd client failed to connect (Attempt(s): {attempt})")
            self._statsd_timerhandle = self.loop.call_later(
                retry_after,
                self._connect_statsd,
                statsd_url,
                retry_after * 2,
                attempt + 1
            )
        self.closing_tasks: List[asyncio.Task] = []
