        referenced: Set[str] = set()
        for el_id in unvisited:
            if el_id not in elements:
                continue
            referenced.update(iter_referenced_ids(elements[el_id]))
        referenced -= element_ids
        element_ids.update(referenced)
        unvisited = referenced
