def maybe_callable(thing, context=None):
    """
    If `thing` is callable, return it.
    If `thing` names a callable attribute of `context`, return it.
    """
    if callable(thing):
        return thing
    if isinstance(thing, six.string_types):
        callable_thing = getattr(context, thing, None)
        if callable(callable_thing):
            base_view_thing = getattr(View, thing, None)
            if not callable(base_view_thing):
                return callable_thing
    return None
