    results_blueprint = Blueprint(
        "results",
        __name__,
        static_url_path="/static/results",
        static_folder=OUTPUT_FOLDER,
    )
    _flask_app.register_blueprint(results_blueprint)
    logger = _flask_app.logger
    return _flask_app
