        if fn is None:
            raise TypeCheckFailure(f"Invalid statement node: {type(node).__name__}")
        with context.internal_memory_scope():
            self.ir_node = fn()
        if self.ir_node is None:
            raise TypeCheckFailure("Statement node did not produce IR")
