            if var is None:
                raise ExecutionError(f"Variable \"{var_name}\" does not exist.")
            sequences = var.split(params.separator, maxsplit=params.max_split)
            for i, var in enumerate(params.split_into):
                try:
                    templates_vars[var] = sequences[i]
