def _v(coord, x, source_srid=4326, target_srid=3857):
    if source_srid == 4326 and x and abs(coord) != HALF_ROTATION_DEG:
        coord -= round(coord / FULL_ROTATION_DEG) * FULL_ROTATION_DEG
    if source_srid == 4326 and target_srid != 4326:
        if x and float(coord) >= 179.999:
            return 179.999
        elif x and float(coord) <= -179.999:
            return -179.999
        if not x and float(coord) >= 89.999:
            return 89.999
        elif not x and float(coord) <= -89.999:
            return -89.999
    return coord
class NotificationCheck(models.Model):
    @classmethod
    def create(cls, name, description, user_threshold, severity=None):
        inst, _ = cls.objects.get_or_create(name=name)
        inst.description = description
        user_thresholds = {}
        for (
            metric_name,
            field_opt,
            use_service,
            use_resource,
            use_label,
            use_event_type,
            minimum,
            maximum,
            thresholds,
            _description,
        ) in user_threshold:
            metric, _ = Metric.objects.get_or_create(name=metric_name)
            steps = cls.get_steps(minimum, maximum, thresholds)
            nm, _ = NotificationMetricDefinition.objects.get_or_create(
                notification_check=inst,
