                description=_description,
                min_value=minimum,
                max_value=maximum,
                steps=len(steps) if steps else None,
                field_option=field_opt,
            )
            user_thresholds[nm.field_name] = {
                "min": minimum,
                "max": maximum,
                "metric": metric_name,
