    to_add = list([k for k in keys if k.valid()])
    for i in range(0, len(old_entries)):
        ent = old_entries[i]
        if not ent.valid():
            continue
        for k in keys:
            if k.base64 == ent.base64:
                ent = k
                if k in to_add:
                    to_add.remove(k)
        old_entries[i] = ent
    for key in to_add:
