        while pos < maximum:
            code = charCodeAt(string, pos)
            if code == 0x0A:
                return result
            if code == 0x3C:
                return result
            if code == 0x3E:
                result.pos = pos + 1
                result.str = unescapeAll(string[start + 1 : pos])
                result.ok = True
                return result
            if code == 0x5C and pos + 1 < maximum:
                pos += 2
                continue
            pos += 1
        return result
