    while pos < maximum:
        code = charCodeAt(string, pos)
        if code == 0x20:
            break
        if code < 0x20 or code == 0x7F:
            break
        if code == 0x5C and pos + 1 < maximum:
            if charCodeAt(string, pos + 1) == 0x20:
                break
            pos += 2
            continue
        if code == 0x28:
            level += 1
            if level > 32:
                return result
        if code == 0x29:
            if level == 0:
                break
            level -= 1
        pos += 1
    if start == pos:
        return result
