class StateBlock(StateBase):
    def __init__(
        self,
        src: str,
        md: MarkdownIt,
        env,
        tokens: list[Token],
        srcCharCode: tuple[int, ...] | None = None,
    ):
        if srcCharCode is not None:
            self._src = src
            self.srcCharCode = srcCharCode
        else:
            self.src = src
        self.md = md
        self.env = env
        self.tokens = tokens
        self.bMarks = []
        self.eMarks = []
        self.tShift = []
        self.sCount = []
        self.bsCount = []
        self.blkIndent = 0
        self.line = 0
        self.lineMax = 0
        self.tight = False
        self.ddIndent = -1
        self.listIndent = -1
        self.parentType = "root"
        self.level = 0
        self.result = ""
        indent_found = False
        start = pos = indent = offset = 0
        length = len(self.src)
        for pos, character in enumerate(self.srcCharCode):
            if not indent_found:
                if isSpace(character):
                    indent += 1
                    if character == 0x09:
                        offset += 4 - offset % 4
                    else:
                        offset += 1
                    continue
                else:
                    indent_found = True
            if character == 0x0A or pos == length - 1:
                if character != 0x0A:
                    pos += 1
                self.bMarks.append(start)
                self.eMarks.append(pos)
                self.tShift.append(indent)
                self.sCount.append(offset)
                self.bsCount.append(0)
                indent_found = False
                indent = 0
                offset = 0
                start = pos + 1
        self.bMarks.append(length)
        self.eMarks.append(length)
        self.tShift.append(0)
        self.sCount.append(0)
        self.bsCount.append(0)
        self.lineMax = len(self.bMarks) - 1
def link(state: StateInline, silent: bool):
    href = ""
    title = ""
    label = None
    oldPos = state.pos
    maximum = state.posMax
    start = state.pos
    parseReference = True
    if state.srcCharCode[state.pos] != 0x5B:
        return False
    labelStart = state.pos + 1
    labelEnd = state.md.helpers.parseLinkLabel(state, state.pos, True)
    if labelEnd < 0:
        return False
    pos = labelEnd + 1
    if pos < maximum and state.srcCharCode[pos] == 0x28:
        parseReference = False
        pos += 1
        while pos < maximum:
            code = state.srcCharCode[pos]
            if not isSpace(code) and code != 0x0A:
                break
            pos += 1
        if pos >= maximum:
            return False
        start = pos
        res = state.md.helpers.parseLinkDestination(state.src, pos, state.posMax)
        if res.ok:
            href = state.md.normalizeLink(res.str)
            if state.md.validateLink(href):
                pos = res.pos
            else:
                href = ""
            start = pos
            while pos < maximum:
                code = state.srcCharCode[pos]
                if not isSpace(code) and code != 0x0A:
                    break
                pos += 1
            res = state.md.helpers.parseLinkTitle(state.src, pos, state.posMax)
            if pos < maximum and start != pos and res.ok:
                title = res.str
                pos = res.pos
                while pos < maximum:
                    code = state.srcCharCode[pos]
                    if not isSpace(code) and code != 0x0A:
                        break
                    pos += 1
        if pos >= maximum or state.srcCharCode[pos] != 0x29:
            parseReference = True
        pos += 1
    if parseReference:
        if "references" not in state.env:
            return False
        if pos < maximum and state.srcCharCode[pos] == 0x5B:
            start = pos + 1
            pos = state.md.helpers.parseLinkLabel(state, pos)
            if pos >= 0:
                label = state.src[start:pos]
                pos += 1
            else:
                pos = labelEnd + 1
        else:
            pos = labelEnd + 1
        if not label:
            label = state.src[labelStart:labelEnd]
        label = normalizeReference(label)
        ref = (
            state.env["references"][label] if label in state.env["references"] else None
        )
        if not ref:
            state.pos = oldPos
            return False
        href = ref["href"]
        title = ref["title"]
    if not silent:
        state.pos = labelStart
        state.posMax = labelEnd
        token = state.push("link_open", "a", 1)
        token.attrs = {"href": href}
        if title:
            token.attrSet("title", title)
        if label and state.md.options.get("store_labels", False):
            token.meta["label"] = label
        state.md.inline.tokenize(state)
        token = state.push("link_close", "a", -1)
    state.pos = pos
    state.posMax = maximum
    return True
def parseLinkDestination(string: str, pos: int, maximum: int) -> _Result:
    lines = 0
    start = pos
    result = _Result()
    if charCodeAt(string, pos) == 0x3C:
        pos += 1
        while pos < maximum:
            code = charCodeAt(string, pos)
            if code == 0x0A:
                return result
            if code == 0x3C:
                return result
            if code == 0x3E:
                result.pos = pos + 1
                result.str = unescapeAll(string[start + 1 : pos])
                result.ok = True
                return result
            if code == 0x5C and pos + 1 < maximum:
                pos += 2
                continue
            pos += 1
        return result
    level = 0
    while pos < maximum:
        code = charCodeAt(string, pos)
        if code == 0x20:
            break
        if code < 0x20 or code == 0x7F:
            break
        if code == 0x5C and pos + 1 < maximum:
            if charCodeAt(string, pos + 1) == 0x20:
                break
            pos += 2
            continue
        if code == 0x28:
            level += 1
            if level > 32:
                return result
        if code == 0x29:
            if level == 0:
                break
            level -= 1
        pos += 1
    if start == pos:
        return result
    if level != 0:
        return result
    result.str = unescapeAll(string[start:pos])
    result.lines = lines
    result.pos = pos
    result.ok = True
    return result
def blockquote(state: StateBlock, startLine: int, endLine: int, silent: bool):
    pos = state.bMarks[startLine] + state.tShift[startLine]
    nextLine = startLine + 1

class GlancesActions(object):
    def set(self, stat_name, criticity):
        """Set the stat_name to criticity."""
        self.status[stat_name] = criticity
    def run(self, stat_name, criticity, commands, repeat, mustache_dict=None):
        """Run the commands (in background).
        - stats_name: plugin_name (+ header)
        - criticity: criticity of the trigger
        - commands: a list of command line with optional {{mustache}}
        - If True, then repeat the action
        - mustache_dict: Plugin stats (can be use within {{mustache}})
        Return True if the commands have been ran.
        """
        if (self.get(stat_name) == criticity and not repeat) or \
           not self.start_timer.finished():
            return False
        logger.debug("{} action {} for {} ({}) with stats {}".format(
            "Repeat" if repeat else "Run",
            commands, stat_name, criticity, mustache_dict))
        for cmd in commands:
            if chevron_tag:
                cmd_full = chevron.render(cmd, mustache_dict)
            else:
                cmd_full = cmd
            logger.info("Action triggered for {} ({}): {}".format(stat_name,
                                                                  criticity,
                                                                  cmd_full))
            logger.debug("Action will be executed with the following command: \
                subprocess.Popen({}, shell=False)".format(cmd_full.split(' ')))
            try:
                Popen(cmd_full.split(' '), shell=False)
            except OSError as e:
                logger.error("Can't execute the action ({})".format(e))
        self.set(stat_name, criticity)
        return True
